export type CollectionsTranslationKey = keyof typeof en;
export function useCollectionsLocalization() {
  const localization = useLocalization();
  const dictionary = localization.language === 'ar' ? ar : en;
  const ct = useCallback(
    (key: CollectionsTranslationKey | string) => dictionary[key as CollectionsTranslationKey] ?? key,
    [dictionary],
  );
  return { ...localization, ct };
}
